import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n_str = next(iterator)
    except StopIteration:
        return
    N = int(n_str)

    word_to_topic = {}
    topics = []

    for _ in range(N):
        topic_name = next(iterator)
        topics.append(topic_name)
        k = int(next(iterator))
        for _ in range(k):
            w = next(iterator)
            word_to_topic[w] = topic_name

    x = int(next(iterator))

    counts = {t: 0 for t in topics}
    for _ in range(x):
        word = next(iterator)
        if word in word_to_topic:
            counts[word_to_topic[word]] += 1

    best_topic = min(topics, key=lambda t: (-counts[t], t))
    print(best_topic)

if __name__ == '__main__':
    main()
